local module = {}
module.__index = module

function module.new()
	local self = setmetatable({}, module)
	self.isScopeStarted = false
	self.isPlayerRemoved = false
	return self
end

-- 如果玩家已经离开，并且作用域未启动，则返回 true
function module:IsCancelled()
	return self.isPlayerRemoved and not self.isScopeStarted
end

return module
